    signalStrength: vhsNum("Signal Strength", 0.25, 0, 1, 0.01, 2),
    colorStripes: vhsNum("Color Stripes", 0.25, 0, 1, 0.01, 2),
    chromaCrawl: vhsNum("Chroma Crawl", 0.2, 0, 1, 0.01, 2),
    chromaLoss: vhsNum("Chroma Loss", 0.05, 0, 1, 0.01, 2),
